const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:900},timezoneId:'Europe/Kyiv'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install({time:new Date('2026-10-22T09:00:00Z')});await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');if(!await p.locator('#learningView').isVisible())throw Error('Missing learning tab');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;profileStorage.removeItem(a.key);if(a.plan().n!==0||a.plan().selected.length!==2)throw Error('Wrong initial plan');a.start();while(a.snapshot()?.queue[a.snapshot().index]){const s=a.snapshot(),item=s.queue[s.index];if(item.intro)document.querySelector('#alContinue').click();a.answer(item.c.de);a.answer(item.c.de);document.querySelector('#alNext').click()}if(DEUTSCH_PROGRESS.snapshot().todayAnswers!==6)throw Error('Answers counted twice');if(a.plan().n!==0||a.plan().selected.length)throw Error('Same-day success unlocks next step');});await p.reload();await p.click('#learningTab');if(await p.locator('#alStart').isEnabled())throw Error('Due dates lost');await p.clock.fastForward(86400000);await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;a.render();a.start();while(a.snapshot()?.queue[a.snapshot().index]){const s=a.snapshot(),item=s.queue[s.index];if(!item.recall)throw Error('No active recall after recognition');a.answer(item.c.de);document.querySelector('#alNext').click()}if(a.plan().n!==1)throw Error('Delayed recall does not unlock verbs');a.start();while(a.snapshot()?.queue[a.snapshot().index]){const s=a.snapshot(),item=s.queue[s.index];if(item.intro)document.querySelector('#alContinue').click();a.answer(item.c.de);document.querySelector('#alNext').click()}if(a.plan().selected.length)throw Error('New daily allowance exceeded');});
await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE,d=JSON.parse(profileStorage.getItem(a.key));for(const c of a.stages[0].cards){d.cards[c.id].due=Date.now();d.cards[c.id].lastSuccess=Date.now()-86400000}profileStorage.setItem(a.key,JSON.stringify(d));a.start();const item=a.snapshot().queue[0];document.querySelector('#alHint').click();a.answer(item.c.de);const x=JSON.parse(profileStorage.getItem(a.key)).cards[item.c.id];if(x.step!==0||Math.abs(x.due-Date.now()-600000)>1000)throw Error('Hint falsely counts as mastery');document.querySelector('#alNext').click();a.answer('wrong');if(a.snapshot().queue.length<3)throw Error('Mistake not returned');setMode('home');if(a.snapshot())throw Error('Navigation did not cancel session');setMode('learning');});
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+width)}
await p.evaluate(()=>{for(const s of DEUTSCH_ADAPTIVE.stages)for(const c of s.cards){const k=c.de.toLowerCase().replace(/[.!?,]/g,'').trim();if(!RECORDED_AUDIO[k])throw Error('Missing whole recording '+c.de)}});
const name=await p.locator('#profileName').textContent();await p.click('#profileButton');await p.fill('#profileAddInput','Adaptive child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(!await p.evaluate(()=>DEUTSCH_ADAPTIVE.plan().n===0&&Object.keys(DEUTSCH_ADAPTIVE.plan().d.cards).length===0))throw Error('Profile data leaked');if(errors.length)throw Error(errors.join(';'));console.log('PASS small prerequisites, delayed recall, daily cap, persistence, hints/errors, navigation, original audio, responsive layout and profile isolation');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
